    /**
     * 僅在「主任核准評量」或「補登／一鍵補登」時呼叫。
     * 堂數制：以「購買堂數 － 已核准筆數」重算剩餘堂數；若算出結果比目前大（不應發生），改為至少扣 1，絕不讓剩餘堂數增加。
     */
    private function deductRemainingSessions(int $studentClassId): void
    {
        $studentClass = StudentClass::where('ID', $studentClassId)
            ->lockForUpdate()
            ->first();

        if (!$studentClass) {
            return;
        }

        $approvedCount = (int) (LearningRecord::where('StudentClassID', $studentClassId)->where('Status', 'approved')->count());
        $oldUsed = $studentClass->UsedSessions;
        $studentClass->UsedSessions = $approvedCount;

        $scheduleMode = $studentClass->ScheduleMode ?? '';
        $purchased = (int) ($studentClass->SessionCount ?? 0);
        $currentRemaining = $studentClass->RemainingSessions;
        $effectiveCurrent = ($currentRemaining !== null && $currentRemaining !== '')
            ? (int) $currentRemaining
            : 0;

        if ($scheduleMode === 'count' || $purchased > 0) {
            $newRemaining = max(0, $purchased - $approvedCount);
            if ($newRemaining > $effectiveCurrent) {
                $newRemaining = max(0, $effectiveCurrent - 1);
            }
            $studentClass->RemainingSessions = $newRemaining;
            $studentClass->Stop = $newRemaining <= 0 ? 1 : ($studentClass->Stop ?? 0);
        }

        $studentClass->save();
    }
