```1:64:/home/admin/backend/app/Models/StudentClass.php
<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;

class StudentClass extends Model
{
    protected $table = 'StudentClass';
    protected $primaryKey = 'ID';
    public $timestamps = false;

    protected $fillable = [
        'StudentID',
        'GradeID',
        'SubjectID',
        'ClassType',
        'TeacherID',
        'by1',
        'Period',
        'StartDate',
        'EndDate',
        'week',
        'time',
        'week1',
        'time1',
        'week2',
        'time2',
        'week3',
        'time3',
        'week4',
        'time4',
        'week5',
        'time5',
        'week6',
        'time6',
        'TotalHours',
        'Memo',
        'Charge',
        'Pay',
        'PayDate',
        'Paid',
        'Disconunt',
        'Rate',
        'LearnTimeID',
        'RoomID',
        'MDate',
        'Stop',
        'ScheduleMode',
        'SessionCount',
        'RemainingSessions',
    ];

    public function student()
    {
        return $this->belongsTo(Student::class, 'StudentID', 'id');
    }

    public function sessions()
    {
        return $this->hasMany(ClassSession::class, 'StudentClassID', 'ID');
    }
}
```

- **Fillable:** `StudentID`, `GradeID`, `SubjectID`, `ClassType`, `TeacherID`, `by1`, `Period`, `StartDate`, `EndDate`, `week`, `time`, `week1`–`week6`, `time1`–`time6`, `TotalHours`, `Memo`, `Charge`, `Pay`, `PayDate`, `Paid`, `Disconunt`, `Rate`, `LearnTimeID`, `RoomID`, `MDate`, `Stop`, `ScheduleMode`, `SessionCount`, `RemainingSessions`.
- **Casts:** none defined.
- **Relationships:** `student()` (belongsTo), `sessions()` (hasMany).
- **Note:** `UsedSessions` is not in `$fillable`; it is updated by `deductRemainingSessions`.
